    fn program_str(&self) -> String {
        // linear strand → arrows; else list the edges
        if self.circuit_rank() == 0 && self.branch_points().is_empty() && self.merge_points().is_empty()
            && self.components() == 1 && self.sources() == 1 && self.sinks() == 1
