109	/// The twelve primitive keys, in canonical navigator/catalog order.
110	pub const PRIMS: [&str; 12] = ["⊢", "⊣", "≻", "≺", "⋈", "⊤", "∈", "∋", "⊙", "⊥", "⊞", "⊡"];
111	
112	/// glyph → ordinal per primitive. The ORDERING is scripture: each primitive's
113	/// constructor order comes from the p4rakernel Lean kernel (`Primitives/Core.lean`)
114	/// and the glyph↔constructor map from `gen_clay_canonical_tuples.py`. ⊤
115	/// (KineticChar: yea<loll<egg<on<air) and ⊞ (Stoichiometry: hung<so<up) were
116	/// CORRECTED here to match scripture — earlier values had ⊤ ords 3/4 swapped
117	/// (𐑺/𐑪) and Σ rotated (𐑳 at 0 instead of 2), which threw the R↔S live-pair
118	/// charge and the ligand↔site complement off (glyph→ctor rendering was unaffected,
119	/// so certify always stayed correct; only the numeric ordinals were wrong).
120	const GLYPHS: [&[(&str, u8)]; 12] = [
121	    /* ⊢ Dimensionality */ &[("𐑛", 0), ("𐑨", 1), ("𐑼", 2), ("𐑦", 3)],
122	    /* ⊣ Topology       */ &[("𐑡", 0), ("𐑰", 1), ("𐑥", 2), ("𐑶", 3), ("𐑸", 4)],
123	    /* > Recognition    */ &[("𐑩", 0), ("𐑑", 1), ("𐑽", 2), ("𐑾", 3)],
124	    /* < Parity         */ &[("𐑗", 0), ("𐑿", 1), ("𐑬", 2), ("𐑯", 3), ("𐑹", 4)],
125	    /* ⋈ Fidelity       */ &[("𐑱", 0), ("𐑞", 1), ("𐑐", 2)],
126	    /* ⊤ Kinetics       */ &[("𐑘", 0), ("𐑤", 1), ("𐑧", 2), ("𐑪", 3), ("𐑺", 4)],
127	    /* ∈ Granularity    */ &[("𐑚", 0), ("𐑔", 1), ("𐑲", 2)],
128	    /* ∋ Composition    */ &[("𐑝", 0), ("𐑜", 1), ("𐑠", 2), ("𐑵", 3)],
129	    /* ⊙ Criticality    */ &[("𐑢", 0), ("⊙", 1), ("𐑮", 2), ("𐑻", 3), ("𐑣", 4)],
130	    /* ⊥ Chirality      */ &[("𐑓", 0), ("𐑒", 1), ("𐑖", 2), ("𐑫", 3)],
131	    /* ⊞ Stoichiometry  */ &[("𐑙", 0), ("𐑕", 1), ("𐑳", 2)],
132	    /* ⊡ Protection     */ &[("𐑷", 0), ("𐑴", 1), ("𐑭", 2), ("𐑟", 3)],
