135	fn ordinal(prim: usize, glyph: &str) -> Option<u8> {
136	    GLYPHS[prim].iter().find(|(g, _)| *g == glyph).map(|(_, o)| *o)
137	}
138	fn max_ord(prim: usize) -> u8 {
139	    GLYPHS[prim].iter().map(|(_, o)| *o).max().unwrap_or(0)
140	}
141	fn glyph_of(prim: usize, ord: u8) -> &'static str {
142	    GLYPHS[prim].iter().find(|(_, o)| *o == ord).map(|(g, _)| *g).unwrap_or("?")
143	}
144	
145	/// The six conjugate pairs (indices into `PRIMS`): the "charge table", an
146	/// involution pairing each primitive with its dual.  D↔W, T↔H, R↔S, P↔F, K↔G, Gm↔Ph.
147	/// The full table; `LIVE_PAIRS` is the active subset for the math register. The
148	/// three non-live pairs (each with a pinned member F/Ph/K) are reserved for the
149	/// addition mode — fusion onto a pinned pole — not the two-pole cycloaddition click.
150	#[allow(dead_code)]
151	pub const CONJUGATE_PAIRS: [(usize, usize); 6] =
152	    [(0, 11), (1, 9), (2, 10), (3, 4), (5, 6), (7, 8)];
153	
154	/// The three LIVE pairs where mathematics actually varies. P↔F (F pinned max),
155	/// K↔G (K pinned low), Gm↔Ph (Ph pinned min) are degenerate in the math
156	/// register, so catalysis is designed only over these three.
157	pub const LIVE_PAIRS: [(usize, usize); 3] = [(0, 11), (1, 9), (2, 10)];
158	pub const LIVE_LABELS: [&str; 3] = ["D↔W", "T↔H", "R↔S"];
159	
160	/// A 12-primitive ordinal tuple (None where the glyph was missing/unknown).
161	#[derive(Clone)]
162	pub struct Tuple {
163	    pub name: String,
164	    pub ord: [Option<u8>; 12],
165	}
166	
167	impl Tuple {
168	    /// Read the twelve glyphs from a catalog entry's raw JSON.
169	    pub fn from_entry(e: &CatalogEntry) -> Tuple {
170	        let mut ord = [None; 12];
171	        for (i, key) in PRIMS.iter().enumerate() {
172	            if let Some(g) = e.raw.get(*key).and_then(|v| v.as_str()) {
173	                ord[i] = ordinal(i, g);
174	            }
175	        }
176	        Tuple { name: e.name.clone(), ord }
177	    }
178	    /// Normalized ordinal on a primitive (ord / max), or None if missing.
179	    pub fn norm(&self, prim: usize) -> Option<f32> {
180	        let m = max_ord(prim);
181	        self.ord[prim].map(|o| if m > 0 { o as f32 / m as f32 } else { 0.0 })
182	    }
183	}
184	
185	/// Signed charge of a fragment on a live pair (x,y): norm(x) − norm(y).
186	fn pair_charge(t: &Tuple, pair: (usize, usize)) -> Option<f32> {
187	    Some(t.norm(pair.0)? - t.norm(pair.1)?)
188	}
189	
190	/// The product of a successful click.
191	pub struct ClickProduct {
192	    pub pair_idx: usize, // index into LIVE_PAIRS — which pair fired
193	    pub drive: f32,      // spring-loaded offset that drove the click
194	    pub product: [Option<u8>; 12],
195	    pub ring: (usize, usize), // the live pair that saturated (formed the ring)
196	    pub inherited: Vec<usize>, // non-clicking primitives the fragments differed on (blended scaffold)
197	}
198	
199	/// Why two fragments do NOT click.
200	pub enum ClickFail {
201	    NoComplementarity,     // no live pair reaches the spring-loaded offset
202	    Ambiguous(Vec<usize>), // >1 live pair complementary — no single reaction center
203	    Missing,               // a tuple couldn't be read
204	}
205	
206	/// A clean click iff **exactly one** live pair is complementary at Δ≥theta
207	/// (opposite charges — one fragment high-x/low-y, the other the reverse), and the
208	/// other live pairs do NOT also fire (a single reaction center — bioorthogonality
209	/// as specificity, not as sameness). The two fragments need not be identical off
210	/// the reaction center; like an azide and an alkyne they are different scaffolds,
211	/// and the product inherits both — the fuse blends the non-clicking axes by join.
212	/// Reliable FFUSE (μ), spring-loaded, closes by construction.
213	pub fn click_pair(a: &Tuple, b: &Tuple, theta: f32) -> Result<ClickProduct, ClickFail> {
214	    // 1. complementarity + drive on each live pair (strict opposite charge)
215	    let mut complementary: Vec<(usize, f32)> = Vec::new();
216	    for (i, &pair) in LIVE_PAIRS.iter().enumerate() {
217	        let (ca, cb) = match (pair_charge(a, pair), pair_charge(b, pair)) {
218	            (Some(x), Some(y)) => (x, y),
219	            _ => return Err(ClickFail::Missing),
220	        };
221	        let opposite = (ca > 0.0 && cb < 0.0) || (ca < 0.0 && cb > 0.0);
222	        let drive = (ca - cb).abs();
223	        if opposite && drive >= theta {
224	            complementary.push((i, drive));
225	        }
226	    }
227	    // 2. selectivity: exactly one reaction center (specificity = orthogonality)
228	    if complementary.is_empty() {
229	        return Err(ClickFail::NoComplementarity);
230	    }
231	    if complementary.len() > 1 {
232	        return Err(ClickFail::Ambiguous(
233	            complementary.iter().map(|(i, _)| *i).collect(),
234	        ));
235	    }
236	    let (pair_idx, drive) = complementary[0];
237	    let ring = LIVE_PAIRS[pair_idx];
238	    // 3. fuse (μ): join (max) on every axis. On the clicking pair the opposite
239	    //    charges bring both members up together — the ring forms. Off it, the
240	    //    product inherits the stronger character of each scaffold.
241	    let mut product = [None; 12];
242	    for p in 0..12 {
243	        product[p] = match (a.ord[p], b.ord[p]) {
244	            (Some(x), Some(y)) => Some(x.max(y)),
245	            (Some(x), None) | (None, Some(x)) => Some(x),
246	            (None, None) => None,
247	        };
248	    }
249	    // 4. record the inherited (blended) non-clicking axes — the scaffold the
250	    //    product carries from both partners, for the report.
251	    let inherited: Vec<usize> = (0..12)
252	        .filter(|&p| p != ring.0 && p != ring.1 && a.ord[p] != b.ord[p])
253	        .collect();
254	    Ok(ClickProduct { pair_idx, drive, product, ring, inherited })
255	}
256	
257	/// Ouroboricity-tier heuristic on a product tuple — ported from
258	/// `cl8nk_navigator.assess_tier`: counts the advanced primitive values a
259	/// self-modeling O_∞ system carries. Score 0–8 → tier.
260	fn tier_score(ord: &[Option<u8>; 12]) -> u8 {
261	    let eq = |i: usize, v: u8| ord[i] == Some(v);
