/// Truth order: positive part (T,t) grows, negative part (F,f) shrinks.
pub fn leq_t(x: Reg16_3, y: Reg16_3) -> bool {
    let pos_ok = (!x.big_t || y.big_t) && (!x.small_t || y.small_t);
    let neg_ok = (!y.big_f || x.big_f) && (!y.small_f || x.small_f);
